contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount == 10, "exact ticket value");
        require(address(this).balance >= amount, "insufficient balance");

        uint bankBefore = c.bank().balance;
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint cBefore = address(c).balance;

        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint cAfter = address(c).balance;
        uint bankAfter = c.bank().balance;

        assert(reverted ||
            (bankAfter >= bankBefore &&
             ((potAfter == 0 && cAfter == cBefore) ||
              (potAfter == potBefore + amount && cAfter == cBefore + amount)))
        );
    }

    receive() external payable {}
}

