pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        amount = 10;
        vm.assume(address(this).balance >= amount);
        uint bankBefore = c.bank().balance;
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        uint cBefore = address(c).balance;
        bool reverted;
        try c.play{value: amount}() { reverted = false; } catch { reverted = true; }
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        uint cAfter = address(c).balance;
        uint bankAfter = c.bank().balance;
        assertTrue(reverted ||
            (bankAfter >= bankBefore &&
             ((potAfter == 0 && cAfter == cBefore) ||
              (potAfter == potBefore + amount && cAfter == cBefore + amount))));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
